from spec_lib import *

T = DEFAULT_TENANT
AMOX = "b3f1c2a0-5d1e-4c7a-9a10-000000000001"

sync_checkpoint = Table(
    schema="ingest", name="sync_checkpoint", cls="SyncCheckpoint", tier="O", scope="MVP",
    purpose="Watermark per (tenant, resource) for the short-interval sales poll (`updated_since`), the nightly reconcile and the intraday intelligence window. One row per resource. This table is the poll checkpoint (D-25).",
    cols=[TENANT(),
          col("resource", "TEXT", "Logical job: sales_poll | sales_reconcile | intel_window | feature_nightly_full."),
          col("high_watermark", "TIMESTAMPTZ", "sales_poll: the SalesPage `high_watermark` of the last poll whose pages were ALL read (never advanced mid-poll); the next poll sends `updated_since = high_watermark - poll_overlap_seconds`. intel_window: max(sales_fact.updated_at) already processed.", null=True),
          col("cursor", "TEXT", "Opaque pagination cursor for an in-progress paged read.", null=True),
          col("last_status", "TEXT", "idle | running | succeeded | failed.", default="'idle'"),
          col("last_started_at", "TIMESTAMPTZ", "Start of the most recent run.", null=True),
          col("last_finished_at", "TIMESTAMPTZ", "End of the most recent run.", null=True),
          col("last_error_code", "TEXT", "Short error code of the most recent failure.", null=True),
          col("consecutive_failures", "INTEGER", "Reset to 0 on success; drives alerting.", default="0"),
          CREATED(), UPDATED()],
    pk=["tenant_id", "resource"],
    checks=[("ck_sync_checkpoint__resource_format", "resource ~ '^[a-z][a-z0-9_]*$'"),
            ("ck_sync_checkpoint__last_status", "last_status IN ('idle','running','succeeded','failed')"),
            ("ck_sync_checkpoint__failures_nonneg", "consecutive_failures >= 0")],
    updated_at_trigger=True, grants="SIU", worker_grants="SIU",
    writer="Sales poller, nightly reconcile and intelligence window (single writer per resource, guarded by `pg_try_advisory_xact_lock(hashtext(tenant||resource))`).",
    readers="Same jobs; ops dashboard (`GET /brain/pipeline/status`).",
    tenancy=TENANCY_STD,
    timestamps="All UTC TIMESTAMPTZ. `high_watermark` is the ERP server clock (from the SalesPage), never the Brain clock.",
    access="Point read/update by primary key once per job run.",
    mutability="Mutable (upsert).",
    retention="Permanent (a handful of rows per tenant).",
    recovery="Reset by deleting the row: the next poll reads everything from `poll_history_start_date` (absolute upsert, so it is safe).",
    migration="Seeded lazily by jobs (INSERT ... ON CONFLICT). No FKs.",
    example={"tenant_id": T, "resource": "sales_poll", "high_watermark": "2026-10-17T10:20:00Z", "last_status": "succeeded", "last_started_at": "2026-10-17T10:20:00Z", "last_finished_at": "2026-10-17T10:20:01Z", "consecutive_failures": 0})

ingest_failure = Table(
    schema="ingest", name="ingest_failure", cls="IngestFailure", tier="O", scope="MVP",
    purpose="Record of a Canonical poll or read the Brain could not process after bounded retries. One open row per (resource, error_code); repeats bump `attempts`. Recovery is the next successful poll or the nightly reconcile, never payload replay.",
    cols=[ID(), TENANT(),
          col("failure_kind", "TEXT", "schema_validation | canonical_read_failed | normalization_error | other."),
          col("resource", "TEXT", "Job that failed, e.g. sales_poll, sales_reconcile, inventory_read."),
          col("error_code", "TEXT", "Stable machine-readable error code."),
          col("error_message", "TEXT", "Sanitised message (<= 500 chars). Never contains customer data.", null=True),
          col("payload_excerpt", "JSONB", "Allow-listed keys only (schema, version, product_ids, business_dates, http_status). No customer fields.", null=True, jsonb="object"),
          col("attempts", "INTEGER", "Failed attempts folded into this open row.", default="1"),
          col("status", "TEXT", "open | resolved | ignored.", default="'open'"),
          col("first_failed_at", "TIMESTAMPTZ", "First failure time.", default="now()"),
          col("last_failed_at", "TIMESTAMPTZ", "Most recent failure time.", default="now()"),
          col("resolved_at", "TIMESTAMPTZ", "When closed.", null=True),
          col("resolved_by", "TEXT", "Actor id (JWT sub) or job name that closed it.", null=True),
          col("resolution", "TEXT", "repolled | fixed | ignored_invalid.", null=True),
          TRACE(), CREATED(), UPDATED()],
    pk=["id"],
    checks=[("ck_ingest_failure__kind", "failure_kind IN ('schema_validation','canonical_read_failed','normalization_error','other')"),
            ("ck_ingest_failure__resource_format", "resource ~ '^[a-z][a-z0-9_]*$'"),
            ("ck_ingest_failure__status", "status IN ('open','resolved','ignored')"),
            ("ck_ingest_failure__attempts", "attempts >= 1"),
            ("ck_ingest_failure__message_len", "error_message IS NULL OR char_length(error_message) <= 500"),
            ("ck_ingest_failure__resolution", "resolution IS NULL OR resolution IN ('repolled','fixed','ignored_invalid')"),
            ("ck_ingest_failure__resolved_consistency", "(status = 'open' AND resolved_at IS NULL) OR (status <> 'open' AND resolved_at IS NOT NULL)")],
    idxs=[Idx("uq_ingest_failure__open_resource_code", ["tenant_id", "resource", "error_code"], unique=True, where="status = 'open'", why="At most one open failure per job and error code, so a poll failing every few minutes bumps `attempts` instead of inserting hundreds of rows."),
          Idx("ix_ingest_failure__tenant_status_failed", ["tenant_id", "status", "last_failed_at"], why="Ops queue of open failures, newest last.")],
    updated_at_trigger=True, grants="SIU", worker_grants="SIU", purge=True,
    writer="Sales poller / canonical client (Ibrahim, D-02).",
    readers="Ops dashboard; pipeline status endpoint; nightly reconcile (decides which days to mark `gap`).",
    tenancy=TENANCY_STD,
    timestamps="UTC TIMESTAMPTZ.",
    jsonb_note="`payload_excerpt`: object, allow-listed keys, validated by Pydantic `PayloadExcerpt` (contracts_jsonb.py); size-bounded by the writer.",
    access="Upsert on failure (`ON CONFLICT (tenant_id, resource, error_code) WHERE status = 'open' DO UPDATE SET attempts = attempts + 1`); list open failures by tenant.",
    mutability="Mutable only through attempts/status/resolution fields.",
    retention="Resolved/ignored rows 90 days; open rows kept until resolved.",
    recovery="The next successful poll resolves the row (`resolution='repolled'`); days still unreadable at the nightly reconcile are marked `gap`.",
    migration="Additive. Partial unique index prevents duplicate open failures.",
    example={"id": "0a7e...-uuid", "tenant_id": T, "failure_kind": "canonical_read_failed", "resource": "sales_poll", "error_code": "DEPENDENCY_UNAVAILABLE", "attempts": 3, "status": "open", "payload_excerpt": {"http_status": 503}})

canonical_cache = Table(
    schema="ingest", name="canonical_cache", cls="CanonicalCache", tier="R", scope="MVP",
    purpose="Local durable cache of validated Canonical JSON (Product, InventoryItem, Supplier, optionally PurchaseOrder) with `synced_at`. NOT a source of truth: it avoids repeated Canonical reads and holds supplier lead times and product attributes needed by the engines.",
    cols=[ID(), TENANT(),
          col("entity_type", "TEXT", "product | inventory_item | supplier | purchase_order."),
          col("entity_id", "TEXT", "Canonical identifier. product/supplier: UUID string. inventory_item: '<product_id>|<location_id>'."),
          col("schema_name", "TEXT", "Canonical schema name, e.g. 'canonical.InventoryItem'."),
          col("schema_version", "TEXT", "Canonical schema `version`, e.g. '1.0'."),
          col("payload", "JSONB", "Validated canonical payload exactly as received (after Pydantic validation).", jsonb="object"),
          col("payload_sha256", "CHAR(64)", "SHA-256 of the canonical-serialised payload; cheap change detection (e.g. supplier lead time changed)."),
          col("source_updated_at", "TIMESTAMPTZ", "ERP `updated_at` carried by the payload. Older payloads never overwrite newer ones.", null=True),
          col("synced_at", "TIMESTAMPTZ", "When the Brain last fetched/confirmed this payload (UTC).", default="now()"),
          CREATED(), UPDATED()],
    pk=["id"],
    uniques=[("uq_canonical_cache__tenant_entity", ["tenant_id", "entity_type", "entity_id"])],
    checks=[("ck_canonical_cache__entity_type", "entity_type IN ('product','inventory_item','supplier','purchase_order')"),
            ("ck_canonical_cache__entity_id_len", "char_length(entity_id) BETWEEN 1 AND 200")],
    idxs=[Idx("ix_canonical_cache__tenant_type_synced", ["tenant_id", "entity_type", "synced_at"], why="Staleness sweeps and 'refresh everything older than X'.")],
    updated_at_trigger=True, grants="SIUD", worker_grants="SIU", purge=True,
    writer="Canonical client (Ibrahim, D-02). Product, inventory and supplier are read on demand by the intelligence window when the cached copy is older than its freshness threshold.",
    readers="Risk engine (supplier lead time, product attrs), recommendation engine, tools via services (never free SQL).",
    tenancy=TENANCY_STD,
    timestamps="`synced_at` = Brain fetch time; `source_updated_at` = ERP clock. UTC.",
    jsonb_note="`payload`: validated against the Canonical JSON Schema / Pydantic model generated from `/contracts/canonical` before insert. Free-text fields (e.g. product names) are untrusted content and must never be inserted into prompts as instructions.",
    access="Point lookup by (tenant_id, entity_type, entity_id); staleness scan by synced_at.",
    mutability="Mutable (upsert). Inventory entries are advisory: decisions that depend on stock re-read Canonical when `synced_at` is older than the freshness threshold in `rule_config(platform)`.",
    retention="Evict entries not refreshed for 30 days.",
    recovery="Fully rebuildable by Canonical reads.",
    migration="Additive. If Canonical bumps `version`, both versions can coexist; `schema_version` records which one the row holds.",
    example={"tenant_id": T, "entity_type": "inventory_item", "entity_id": AMOX + "|main-store", "schema_name": "canonical.InventoryItem", "schema_version": "1.0", "payload": {"available_quantity": 40, "reorder_point": 50}, "synced_at": "2026-09-24T10:16:42Z"})

sales_fact = Table(
    schema="ingest", name="sales_fact", cls="SalesFact", tier="R", scope="MVP",
    purpose="Daily sales per product (product x business day), copied from the polled Canonical `DailySalesTotal`. The only persisted sales data in the Brain; aggregate, not per-sale-line. Every write is an absolute upsert keyed (tenant, product, date) that keeps the newest ERP `updated_at` (D-25), so re-reading a row is always harmless.",
    cols=[ID(), TENANT(),
          col("product_id", "UUID", "Canonical product id (external reference; see OD-02)."),
          col("sales_date", "DATE", "Canonical `business_date`, computed by the ERP in the tenant timezone (D-04, OD-03)."),
          col("units_sold", "NUMERIC(14,3)", "Gross units sold that day (Canonical `units_sold`).", default="0"),
          col("units_returned", "NUMERIC(14,3)", "Units returned that day (Canonical `units_returned`).", default="0"),
          col("net_units", "NUMERIC(14,3)", "units_sold - units_returned (Canonical `net_units`). Demand = net units (D-06). May be negative only if returns exceed sales that day; the feature label clamps it at 0.", default="0"),
          col("day_status", "TEXT", "Canonical `day_status`: open (the ERP day is still running) | closed."),
          col("is_complete", "BOOLEAN", "Canonical `complete`. false = the ERP cannot vouch for this total; the day is excluded from training (D-06).", default="true"),
          col("source_updated_at", "TIMESTAMPTZ", "Canonical `updated_at` (ERP clock). The upsert only replaces the row when the incoming value is >= this one."),
          col("source_mode", "TEXT", "poll (short-interval incremental poll) | reconcile (nightly re-read of the last N days) | backfill (manual range).", default="'poll'"),
          col("polled_at", "TIMESTAMPTZ", "When the Brain last read this row from Canonical (UTC).", default="now()"),
          CREATED(), UPDATED()],
    pk=["id"],
    uniques=[("uq_sales_fact__tenant_product_date", ["tenant_id", "product_id", "sales_date"])],
    checks=[("ck_sales_fact__units_nonneg", "units_sold >= 0"),
            ("ck_sales_fact__returned_nonneg", "units_returned >= 0"),
            ("ck_sales_fact__net_consistency", "net_units = units_sold - units_returned"),
            ("ck_sales_fact__day_status", "day_status IN ('open','closed')"),
            ("ck_sales_fact__source_mode", "source_mode IN ('poll','reconcile','backfill')")],
    idxs=[Idx("ix_sales_fact__tenant_sales_date", ["tenant_id", "sales_date"], why="Date-range scans: nightly reconcile, BI top-N, per-day batch scoring."),
          Idx("ix_sales_fact__tenant_updated_at", ["tenant_id", "updated_at"], why="Change detection: which products changed since the intelligence-window watermark (the 'dirty' set) and the incremental feature job.")],
    updated_at_trigger=True, grants="SIU", worker_grants="SIU",
    writer="Sales poller (every `sales_poll_interval_seconds`), nightly reconcile, manual backfill - Ibrahim (D-02).",
    readers="Feature pipeline, anomaly engine, BI (`get_sales_history` summaries), evaluation (actuals).",
    tenancy=TENANCY_STD,
    timestamps="`sales_date` is a DATE in the tenant business timezone; all other timestamps UTC. `updated_at` (Brain clock) is the change-detection key for downstream jobs; `source_updated_at` (ERP clock) is only the stale-overwrite guard.",
    access="Upsert by (tenant_id, product_id, sales_date) `... DO UPDATE ... WHERE EXCLUDED.source_updated_at >= sales_fact.source_updated_at`; range scans by date; per-product history scans via the unique index.",
    mutability="Mutable. Always absolute (never incremented), so duplicates, overlaps and out-of-order pages are harmless.",
    retention="Keep >= 3 years (seasonality needs full years). Rebuildable, so no archive.",
    recovery="Rebuild with a Canonical backfill over any date range; set `source_mode='backfill'`, then mark days complete in `sales_day_coverage`.",
    migration="Additive columns only. Grain is organization-level (N-05): one row per (tenant, product, business date) for the whole organization; branch-level forecasting is deferred. A product x location split would add `location_id` and change the unique key - a breaking migration.",
    example={"tenant_id": T, "product_id": AMOX, "sales_date": "2026-10-16", "units_sold": 26, "units_returned": 2, "net_units": 24, "day_status": "closed", "is_complete": True, "source_updated_at": "2026-10-16T22:05:00Z", "source_mode": "reconcile", "polled_at": "2026-10-17T00:02:00Z"})

sales_day_coverage = Table(
    schema="ingest", name="sales_day_coverage", cls="SalesDayCoverage", tier="O", scope="MVP",
    purpose="Per tenant-day statement of whether Brain sales data for that day is authoritative. Lets the feature job distinguish a TRUE zero-sales day from a MISSING day (source rule: never treat missing days as zero silently).",
    cols=[TENANT(),
          col("business_date", "DATE", "Business date (tenant timezone)."),
          col("status", "TEXT", "open (ERP day still running) | complete (closed, fully read, ERP vouches for it) | gap (known hole: excluded from training).", default="'open'"),
          col("verified_via", "TEXT", "reconcile | backfill. Required when complete.", null=True),
          col("verified_at", "TIMESTAMPTZ", "When the day was verified against Canonical.", null=True),
          col("gap_reason", "TEXT", "erp_incomplete | canonical_unavailable | validation_failures | unknown. Required when gap.", null=True),
          CREATED(), UPDATED()],
    pk=["tenant_id", "business_date"],
    checks=[("ck_sales_day_coverage__status", "status IN ('open','complete','gap')"),
            ("ck_sales_day_coverage__verified_via", "verified_via IS NULL OR verified_via IN ('reconcile','backfill')"),
            ("ck_sales_day_coverage__gap_reason", "gap_reason IS NULL OR gap_reason IN ('erp_incomplete','canonical_unavailable','validation_failures','unknown')"),
            ("ck_sales_day_coverage__complete_verified", "status <> 'complete' OR (verified_at IS NOT NULL AND verified_via IS NOT NULL)"),
            ("ck_sales_day_coverage__gap_reason_required", "status <> 'gap' OR gap_reason IS NOT NULL")],
    idxs=[Idx("ix_sales_day_coverage__tenant_status_date", ["tenant_id", "status", "business_date"], why="Find open/gap days to reconcile.")],
    updated_at_trigger=True, grants="SIU", worker_grants="SIU",
    writer="Sales poller (inserts `open`), nightly reconcile and backfill (set `complete` or `gap`) - Ibrahim (D-02).",
    readers="Feature pipeline (zero vs missing), forecasting validation, ops.",
    tenancy=TENANCY_STD,
    timestamps="DATE in tenant business timezone; other columns UTC.",
    access="Range read by date for a tenant; upsert per day.",
    mutability="Mutable: open -> complete, or open -> gap -> complete after a later reconcile/backfill.",
    retention="Permanent (one row per tenant-day, about 365 per year).",
    recovery="Rebuildable by re-running reconcile for the date range.",
    migration="Additive; tiny table.",
    example={"tenant_id": T, "business_date": "2026-10-16", "status": "complete", "verified_via": "reconcile", "verified_at": "2026-10-17T00:02:00Z"})

calendar_day = Table(
    schema="feat", name="calendar_day", cls="CalendarDay", tier="R", scope="MVP",
    purpose="Known-in-advance calendar attributes (holiday, Ramadan, flu season) per tenant calendar. Source of the calendar features copied into `feature_daily`.",
    cols=[TENANT(),
          col("calendar_date", "DATE", "Calendar date in the tenant business timezone."),
          col("is_holiday", "BOOLEAN", "Official holiday.", default="false"),
          col("holiday_name", "TEXT", "Holiday label, when is_holiday.", null=True),
          col("is_ramadan", "BOOLEAN", "Within Ramadan.", default="false"),
          col("is_flu_season", "BOOLEAN", "Within the configured cold/flu season window.", default="false"),
          col("source", "TEXT", "seed (generated by seed script) | manual (curated override).", default="'seed'"),
          CREATED(), UPDATED()],
    pk=["tenant_id", "calendar_date"],
    checks=[("ck_calendar_day__holiday_name", "holiday_name IS NULL OR is_holiday"),
            ("ck_calendar_day__source", "source IN ('seed','manual')")],
    updated_at_trigger=True, grants="SIU", worker_grants="S",
    writer="Calendar seed script (Ibrahim, D-02); manual overrides by admin script.",
    readers="Feature pipeline.",
    tenancy=TENANCY_STD + " Calendars are per tenant because country/holidays differ.",
    timestamps="DATE only plus UTC audit timestamps.",
    access="Range read by date for a tenant.",
    mutability="Mutable but rarely. A change triggers a feature recompute for the affected dates.",
    retention="Permanent.",
    recovery="Reseed with the seed script (source library chosen in OD-14).",
    migration="Seed years 2020-2030 in the seed step, not in the schema migration.",
    example={"tenant_id": T, "calendar_date": "2026-09-24", "is_holiday": False, "is_ramadan": False, "is_flu_season": False, "source": "seed"})

feature_daily = Table(
    schema="feat", name="feature_daily", cls="FeatureDaily", tier="R", scope="MVP",
    purpose="One wide, typed feature row per (tenant, product, day). Single table serving training, backtesting, anomaly scoring and inference through `FeatureStore.get_features(product_id, date)`. Feature row for day d uses information from days < d only plus known-in-advance calendar data.",
    cols=[TENANT(),
          col("product_id", "UUID", "Canonical product id (external reference)."),
          col("feature_date", "DATE", "Day the features describe/predict (business date)."),
          col("feature_set_version", "SMALLINT", "Version of the feature definition that produced the row. Models record the version they were trained on; inference refuses a mismatch."),
          col("y_units", "NUMERIC(14,3)", "LABEL: realised demand on feature_date = GREATEST(sales_fact.net_units, 0). NULL unless y_status is observed or zero_filled. Never a model input.", null=True),
          col("y_status", "TEXT", "observed (sales_fact row on a complete day) | zero_filled (no row on a complete day = true zero) | missing (day not complete) | open (current day) | future."),
          col("is_outlier", "BOOLEAN", "Outlier flag (marked, never deleted; training winsorises, anomaly detector still sees it).", default="false"),
          col("history_days", "INTEGER", "Count of complete days (observed or zero_filled) before feature_date since the product's first sale. Drives cold-start routing.", default="0"),
          col("n_obs_7", "SMALLINT", "Complete days inside the trailing 7-day window (0..7)."),
          col("n_obs_28", "SMALLINT", "Complete days inside the trailing 28-day window (0..28)."),
          col("lag_1", "NUMERIC(14,3)", "Units on feature_date - 1; NULL if that day is not complete.", null=True),
          col("lag_7", "NUMERIC(14,3)", "Units on feature_date - 7.", null=True),
          col("lag_14", "NUMERIC(14,3)", "Units on feature_date - 14.", null=True),
          col("lag_28", "NUMERIC(14,3)", "Units on feature_date - 28.", null=True),
          col("roll_mean_7", "NUMERIC(14,4)", "Trailing 7-day mean over complete days; NULL if n_obs_7 < 5.", null=True),
          col("roll_mean_14", "NUMERIC(14,4)", "Trailing 14-day mean; NULL if fewer than 10 complete days.", null=True),
          col("roll_mean_28", "NUMERIC(14,4)", "Trailing 28-day mean; NULL if n_obs_28 < 21.", null=True),
          col("roll_std_7", "NUMERIC(14,4)", "Trailing 7-day sample std dev.", null=True),
          col("roll_std_28", "NUMERIC(14,4)", "Trailing 28-day sample std dev.", null=True),
          col("dow", "SMALLINT", "Day of week, Monday=0 .. Sunday=6."),
          col("month", "SMALLINT", "Month 1..12."),
          col("day_of_month", "SMALLINT", "1..31."),
          col("week_of_year", "SMALLINT", "ISO week 1..53."),
          col("is_holiday", "BOOLEAN", "Copied from calendar_day.", default="false"),
          col("is_ramadan", "BOOLEAN", "Copied from calendar_day.", default="false"),
          col("is_flu_season", "BOOLEAN", "Copied from calendar_day.", default="false"),
          col("is_promotion", "BOOLEAN", "NULL = unknown. The Canonical contract has no promotion data in the MVP, so this is always NULL (documented limitation, guide section 7.8).", null=True),
          col("computed_at", "TIMESTAMPTZ", "When this row was (re)computed (UTC).", default="now()"),
          col("compute_mode", "TEXT", "incremental | nightly_full | backfill."),
          col("inputs_max_updated_at", "TIMESTAMPTZ", "max(sales_fact.updated_at) over the rows used. Row is stale if any input row is newer.", null=True)],
    pk=["tenant_id", "product_id", "feature_date"],
    checks=[("ck_feature_daily__version", "feature_set_version > 0"),
            ("ck_feature_daily__y_status", "y_status IN ('observed','zero_filled','missing','open','future')"),
            ("ck_feature_daily__y_consistency", "(y_status IN ('observed','zero_filled')) = (y_units IS NOT NULL)"),
            ("ck_feature_daily__zero_filled", "y_status <> 'zero_filled' OR y_units = 0"),
            ("ck_feature_daily__y_nonneg", "y_units IS NULL OR y_units >= 0"),
            ("ck_feature_daily__history_nonneg", "history_days >= 0"),
            ("ck_feature_daily__n_obs_7", "n_obs_7 BETWEEN 0 AND 7"),
            ("ck_feature_daily__n_obs_28", "n_obs_28 BETWEEN 0 AND 28"),
            ("ck_feature_daily__dow", "dow BETWEEN 0 AND 6"),
            ("ck_feature_daily__month", "month BETWEEN 1 AND 12"),
            ("ck_feature_daily__dom", "day_of_month BETWEEN 1 AND 31"),
            ("ck_feature_daily__woy", "week_of_year BETWEEN 1 AND 53"),
            ("ck_feature_daily__compute_mode", "compute_mode IN ('incremental','nightly_full','backfill')")],
    idxs=[Idx("ix_feature_daily__tenant_date", ["tenant_id", "feature_date"], why="Per-day batch scoring (anomaly sweep, nightly inference for all products).")],
    grants="SIU", worker_grants="SIU", purge=True,
    writer="Feature pipeline (incremental for products whose sales_fact rows changed since the last poll; nightly full) - Abdelrahman. Review of feature usefulness: Ibrahim.",
    readers="Forecasting (training, backtest, inference), anomaly engine, risk (rarely) - through `FeatureStore` only.",
    tenancy=TENANCY_STD,
    timestamps="`feature_date` DATE (business tz). `computed_at` UTC. No `updated_at`: the row is replaced by upsert and `computed_at` is its version clock.",
    access="Point read (tenant, product, date) for get_features; range read per product for training; per-date scan across products.",
    mutability="Replaced by upsert on recompute. Persisted rows exist for dates <= current business date + 1; multi-step future features are built in memory by the same pure function.",
    retention="30 months of rows (covers a 24-month training window plus margin).",
    recovery="Fully rebuildable from sales_fact + sales_day_coverage + calendar_day (nightly full recompute is the safety net for any missed invalidation).",
    migration="Wide-table additive columns + bump `feature_set_version` + full recompute. Never repurpose a column. Dropping a column only after every validated model that used it is retired.",
    example={"tenant_id": T, "product_id": AMOX, "feature_date": "2026-09-24", "feature_set_version": 1, "y_units": 22, "y_status": "observed", "history_days": 112, "n_obs_7": 7, "n_obs_28": 28, "lag_1": 22, "lag_7": 25, "roll_mean_7": 23.4, "dow": 3, "month": 9, "is_holiday": False, "is_promotion": None, "compute_mode": "nightly_full"})

TABLES_INGEST = [sync_checkpoint, ingest_failure, canonical_cache, sales_fact, sales_day_coverage, calendar_day, feature_daily]
